document.addEventListener('click',e=>{if(e.target.id==='submitLessonTest'){const j=getJourney(),qs=lessonQuestions(j.current),answers=$$('.lesson-answer');let score=0;answers.forEach((a,i)=>{if(a.value.trim().toLowerCase().includes(qs[i].a))score++});j.bestScore=Math.max(j.bestScore,score);j.testPassed=score>=2;store.set('lessonJourney',j);lessonsPage();toast(j.testPassed?'Test réussi ! — Test passed!':`Score ${score}/3 — Réessaie — Try again`)}if(e.target.id==='nextLesson'){const j=getJourney();if(j.testPassed&&lessonRemaining(j)===0){const completed=store.get('completedLessons',[]);if(!completed.includes(j.current))completed.push(j.current);store.set('completedLessons',completed);addHistory('lesson',lessonLibrary[j.current%lessonLibrary.length].title,'Terminé — Complete');store.set('lessonJourney',{current:(j.current+1)%lessonLibrary.length,startedAt:Date.now(),testPassed:false,bestScore:0});store.set('lessonNotes_'+j.current,'');lessonsPage();toast('Nouveau sujet débloqué — New topic unlocked')}}const pick=e.target.closest('[data-companion]');if(pick){store.set('companion',pick.dataset.companion);companionPage();toast('Compagnon choisi ! — Companion selected!')}if(e.target.id==='companionBubble')$('#companionPopover')?.classList.toggle('open');if(e.target.id==='closeCompanion')$('#companionPopover')?.classList.remove('open')});
const progressKey=k=>/^(history|favorites|quizUsed|watchedVideo_|storyDraft|testDraft|completedLessons|lessonJourney|lessonNotes_|lessonMissions_|companionChat_|pet_)/.test(k);
const store={get(k,d){if(window.pmGuest&&progressKey(k))return d;try{return JSON.parse(localStorage.getItem('pm_'+k))??d}catch{return d}},set(k,v){if(window.pmGuest&&progressKey(k))return;localStorage.setItem('pm_'+k,JSON.stringify(v))}};
