function applySettings(){document.documentElement.dataset.theme=settings.theme;document.documentElement.style.setProperty('--font-scale',settings.font);document.documentElement.classList.toggle('high-contrast',settings.contrast);document.documentElement.classList.toggle('reduced-motion',settings.reduced);}
function saveSettings(){store.set('settings',settings);applySettings()}
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function addHistory(type,title,score='',data={}){history.unshift({id:Date.now(),type,title,score,date:new Date().toISOString(),data});store.set('history',history)}
function route(){const requested=location.hash.slice(1).split('?')[0]||'home';return nav.some(item=>item[0]===requested)?requested:'home'}
function go(r){location.hash=r}
function renderNav(){ $('#nav').innerHTML=nav.map(n=>`<button type="button" class="nav-btn ${route()===n[0]?'active':''}" data-route="${n[0]}"><span>${n[1]}</span>${B(n[2],n[3])}</button>`).join('')+(user?`<button type="button" class="nav-btn logout-btn" id="logoutBtn" aria-label="Déconnexion — Log out"><span>↪</span>${B('Déconnexion','Log out')}</button>`:''); const n=nav.find(x=>x[0]===route())||nav[0];$('#crumb').innerHTML=`${n[2]} <small>— ${n[3]}</small>`;$('#userLabel').innerHTML=user?`${user.name}<small>${user.guest?'Mode invité — Guest mode':'Membre — Member'}</small>`:'Invité<small>Guest</small>';$('#userAvatar').textContent=user?user.name[0].toUpperCase():'?'; }
function layout(title,en,intro,body){return `<header><p class="eyebrow">Petit Monde</p><h1>${title}<small class="en">${en}</small></h1>${intro?`<p class="muted">${intro}</p>`:''}</header>${body}`}
function render(){renderNav();applyUserAvatar();$('#sidebar').classList.remove('open');document.body.classList.remove('menu-open');const p=route();document.body.dataset.page=p;({home:homePage,lessons:lessonsPage,videos:categorizedVideosPage,quiz:quizPage,tests:testSetup,poems:poemPage,activity:activityPage,companion:companionPage,avatar:avatarPage,progress:progressPage,history:historyPage,settings:settingsPage}[p]||homePage)();if(p==='home'){addTrustBanner();enhanceHomeDashboard()}if(p==='videos'){enhanceStoryVideos();enhanceFrenchEssentialsLessons()}if(p==='avatar'){enhanceAvatarStudio();addGenderAvatarOptions();addThemedAvatarOptions()}if(p==='settings')enhanceSettingsMusic();enhanceAppShell(p);addCompanionWidget(p);$('#content').focus({preventScroll:true});window.scrollTo(0,0)}
function applyUserAvatar(){if(!user||user.guest)return;const a=store.get('avatar',null);if(a){$('#userAvatar').textContent=a.icon;$('#userAvatar').style.background=a.color;$('.avatar-btn').textContent=a.icon;$('.avatar-btn').style.background=a.color}}
function addTrustBanner(){const banner=document.createElement('section');banner.className='trust-banner';banner.innerHTML=`<div class="trust-icon">🛡️</div><div><strong>${user?.guest?'Mode invité — Guest mode':'Ton espace personnel — Your personal space'}</strong><p>${user?.guest?'Tu peux explorer librement. Tes activités restent sur cet appareil. — Explore freely. Your activity stays on this device.':'Bienvenue, '+user.name+'. Tes préférences et progrès sont enregistrés uniquement dans ce navigateur. — Your preferences and progress are stored only in this browser.'}</p></div><div class="trust-pills"><span>🔒 Privé — Private</span><span>💾 Sauvegarde locale — Local save</span><span>✓ Sans publicité — Ad-free</span></div>`;const hero=$('.hero');hero?.insertAdjacentElement('afterend',banner)}
function homePage(){const completed=history.filter(x=>x.type==='quiz'||x.type==='test').length;$('#page').innerHTML=`<section class="hero"><div><p class="eyebrow">Bonjour, ${user?.name||'ami'} ! — Hello, ${user?.name||'friend'}!</p><h1>Un petit pas,<br>une grande aventure.<small class="en">One small step, one big adventure.</small></h1><p class="muted">Lis, joue, écris et apprends à ton rythme. — Read, play, write, and learn at your own pace.</p><div class="actions"><button class="btn primary" data-route="quiz">Commencer un quiz — Start a quiz</button><button class="btn" data-route="activity">Créer une histoire — Create a story</button></div></div><div class="hero-art" aria-hidden="true">🌿</div></section><div class="section-head"><div><p class="eyebrow">Aujourd’hui — Today</p><h2>Que veux-tu explorer ?<small class="en">What would you like to explore?</small></h2></div></div><div class="grid">${[['quiz','◈','Quiz rapide','Quick quiz'],['poems','❦','Poèmes apaisants','Calming poems'],['activity','✦','Atelier d’histoire','Story workshop']].map(x=>`<button class="card clickable" data-route="${x[0]}"><span class="card-icon">${x[1]}</span>${B(x[2],x[3],'h3')}</button>`).join('')}</div><div class="section-head"><h2>Ton parcours<small class="en">Your journey</small></h2></div><div class="grid"><div class="card"><div class="stat">${completed}</div>${B('activités terminées','activities completed')}</div><div class="card"><div class="stat">${favorites.length}</div>${B('poèmes favoris','favorite poems')}</div><div class="card"><div class="stat">${history.filter(x=>x.type==='story').length}</div>${B('histoires écrites','stories written')}</div></div>`}
function videosPage(){const watched=store.get('watchedVideo_t74ZmtDVZ7k',false);$('#page').innerHTML=layout('Vidéos en français','French videos','Regarde, écoute et apprends avec une vidéo sélectionnée. — Watch, listen, and learn with a selected video.',`<section class="single-video-card"><div class="single-video-player"><iframe src="https://www.youtube-nocookie.com/embed/t74ZmtDVZ7k?rel=0&cc_load_policy=1&cc_lang_pref=en&hl=fr" title="Vidéo française — French video" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><div class="single-video-info"><span class="pill">▶ YouTube · Français</span><h2>Vidéo française sélectionnée<small class="en">Selected French video</small></h2><p>Écoute attentivement le français et active les sous-titres anglais si nécessaire. — Listen carefully to the French and enable English subtitles if needed.</p><div class="caption-guide"><b>CC</b><span><strong>Sous-titres anglais — English subtitles</strong><small>Dans le lecteur : ⚙ → Sous-titres → English. Leur disponibilité dépend de la vidéo. — In the player: ⚙ → Subtitles → English. Availability depends on the video.</small></span></div><div class="actions"><button class="btn primary" id="markMainVideoWatched" ${watched?'disabled':''}>${watched?'✓ Regardée — Watched':'Marquer comme regardée — Mark watched'}</button><a class="btn" href="https://youtu.be/t74ZmtDVZ7k?si=u9JtNJMtgEyLzxAd" target="_blank" rel="noopener noreferrer">Ouvrir sur YouTube — Open on YouTube ↗</a></div></div></section><section class="video-learning-tips"><article><span>1</span><div><strong>Écoute une première fois</strong><small>Listen once without stopping</small></div></article><article><span>2</span><div><strong>Relis avec les sous-titres</strong><small>Watch again with subtitles</small></div></article><article><span>3</span><div><strong>Répète trois phrases</strong><small>Repeat three sentences aloud</small></div></article></section><div class="embed-help card"><span>💡</span><p><strong>Le lecteur ne fonctionne pas ? — Player not working?</strong><small>Les pages ouvertes directement avec <code>file://</code> peuvent être bloquées par YouTube. Utilise le bouton « Ouvrir sur YouTube » ci-dessus. — Pages opened directly with <code>file://</code> may be blocked by YouTube. Use the “Open on YouTube” button above.</small></p></div>`)}
function configureVideoEmbed(){const frame=$('.single-video-player iframe'),help=$('.embed-help');if(!frame)return;const hosted=/^https?:$/.test(location.protocol),origin=hosted?`&origin=${encodeURIComponent(location.origin)}`:'';frame.referrerPolicy='origin-when-cross-origin';frame.src=`https://www.youtube.com/embed/t74ZmtDVZ7k?rel=0&playsinline=1&cc_load_policy=1&cc_lang_pref=en&hl=fr${origin}`;if(help&&hosted){help.classList.add('server-ready');help.innerHTML='<span>✓</span><p><strong>Lecteur connecté à ton site — Player connected to your website</strong><small>La vidéo reste intégrée ici. — The video remains embedded here.</small></p>'}else if(help){help.classList.add('file-warning');help.innerHTML='<span>⚠️</span><p><strong>Ouvre le site avec START-SITE.bat — Open with START-SITE.bat</strong><small>YouTube bloque souvent les lecteurs lancés depuis une adresse <code>file://</code>. Ferme cette page et double-clique sur le fichier de démarrage pour ouvrir <code>http://localhost:8080</code>. — YouTube often blocks players opened from <code>file://</code>. Close this page and double-click the starter file.</small></p>'}}
