function getJourney(){let j=store.get('lessonJourney',null);if(!j){j={current:0,startedAt:Date.now(),testPassed:false,bestScore:0};store.set('lessonJourney',j)}return j}
function lessonRemaining(j){return Math.max(0,48*60*60*1000-(Date.now()-j.startedAt))}
function formatRemaining(ms){const h=Math.floor(ms/36e5),m=Math.floor(ms%36e5/6e4);return `${h} h ${m} min`}
function lessonsPage(){const j=getJourney(),l=lessonLibrary[j.current%lessonLibrary.length],remaining=lessonRemaining(j),ready=remaining===0&&j.testPassed;$('#page').innerHTML=layout('Parcours guidé','Guided lesson journey','Un seul sujet est attribué automatiquement. Étudie-le pendant au moins 48 heures et réussis son test écrit pour avancer. — One topic is assigned automatically. Study it for at least 48 hours and pass its written test to advance.',`<div class="guided-lesson lesson-${l.color}"><div class="guided-head"><span class="lesson-emoji">${l.icon}</span><div><p class="eyebrow">Sujet actuel — Current topic</p><h2>${l.title}<small class="en">${l.en}</small></h2><span class="pill">${l.level}</span></div><div class="lesson-clock"><strong>${remaining?formatRemaining(remaining):'48 h ✓'}</strong><small>temps d’étude restant<br>study time remaining</small></div></div><div class="study-path"><article class="study-unit"><b>1</b><div><h3>Découvrir — Discover</h3><p>Lis et écoute chaque expression plusieurs fois. — Read and listen to each expression several times.</p>${l.words.map(w=>`<button class="option" data-speak-word="${w.split(' — ')[0]}">🔊 ${w}</button>`).join('')}</div></article><article class="study-unit"><b>2</b><div><h3>Comprendre — Understand</h3><p>Crée une phrase avec chaque expression et répète-la à voix haute. — Make a sentence with each expression and repeat it aloud.</p><div class="lesson-tip">💡 ${lessonExamples[j.current%lessonExamples.length]}</div></div></article><article class="study-unit"><b>3</b><div><h3>Pratiquer — Practice</h3><p>Reviens chaque jour pendant ta période de 48 heures. Ton travail est sauvegardé automatiquement. — Return each day during your 48-hour period. Your work saves automatically.</p><textarea id="lessonNotes" placeholder="Mes phrases et mes notes… — My sentences and notes…">${store.get('lessonNotes_'+j.current,'')}</textarea></div></article></div><section class="written-check"><h2>Test écrit obligatoire<small class="en">Required written assessment</small></h2><p>Obtiens au moins 2 réponses correctes sur 3. — Get at least 2 of 3 answers correct.</p>${lessonQuestions(j.current).map((q,i)=>`<div class="field"><label>${i+1}. ${q.q}<small class="en">${q.en}</small></label><input class="lesson-answer" data-index="${i}" autocomplete="off"></div>`).join('')}<button class="btn primary" id="submitLessonTest">Corriger mon test — Check my test</button><p id="lessonTestFeedback" class="${j.testPassed?'success':''}">${j.testPassed?`✓ Test réussi — Test passed (${j.bestScore}/3)`:j.bestScore?`Meilleur score — Best score: ${j.bestScore}/3`:''}</p></section><div class="unlock-panel ${ready?'ready':''}"><div><strong>${j.testPassed?'✓':'○'} Test écrit — Written test</strong><strong>${remaining===0?'✓':'○'} 48 heures d’étude — 48 study hours</strong></div><button class="btn primary" id="nextLesson" ${ready?'':'disabled'}>Passer au sujet suivant — Move to next topic</button></div></div>`);enhanceLessonPage();clearInterval(window.lessonClockTimer);if(remaining)window.lessonClockTimer=setInterval(()=>{if(route()==='lessons')lessonsPage()},60000)}
