function enhanceLessonPage(){const test=$('.written-check');if(!test)return;const j=getJourney(),l=lessonLibrary[j.current%lessonLibrary.length],m=lessonMissionState(j.current),today=new Date().toISOString().slice(0,10),checked=m.checkins.includes(today),pairs=l.words.map(w=>w.split(' — ')),scene=lessonScenes[j.current%lessonScenes.length],target=pairs[m.cards%pairs.length],companion=companions.find(c=>c.id===store.get('companion',null));test.insertAdjacentHTML('beforebegin',`<section class="lesson-adventure"><div class="quest-banner"><div><p class="eyebrow">Aventure du jour — Today’s adventure</p><h2>Joue, parle et gagne des étoiles !<small class="en">Play, speak, and earn stars!</small></h2></div><div class="lesson-xp">⭐ <strong>${m.xp}</strong><small>XP</small></div></div><div class="mission-progress"><span style="--done:${[checked,m.matchDone,m.sceneDone].filter(Boolean).length/3*100}%"></span></div><div class="mission-grid"><article class="mission-card daily ${checked?'complete':''}"><span class="mission-icon">${checked?'✅':'🌞'}</span><h3>Visite quotidienne<small class="en">Daily check-in</small></h3><p>${checked?'Mission accomplie aujourd’hui ! — Mission complete today!':'Reviens chaque jour pour construire ta série. — Return daily to build your streak.'}</p><button class="btn" id="lessonCheckin" ${checked?'disabled':''}>${checked?'Réclamé — Claimed':'Réclamer +10 XP — Claim +10 XP'}</button><b>${m.checkins.length} jour${m.checkins.length===1?'':'s'} — day streak</b></article><article class="mission-card match ${m.matchDone?'complete':''}"><span class="mission-icon">🧩</span><h3>Mot mystère<small class="en">Mystery word</small></h3><p>Quel mot signifie <strong>“${target[1]}”</strong> ?</p><div class="mini-choices">${pairs.map(p=>`<button data-lesson-match="${E(p[0])}" data-correct="${p[0]===target[0]}">${p[0]}</button>`).join('')}</div><small id="matchFeedback">${m.matchDone?'✓ Trouvé ! — Found it!':''}</small></article><article class="mission-card scene ${m.sceneDone?'complete':''}"><span class="mission-icon">🎭</span><h3>Mission réelle<small class="en">Real-life mission</small></h3><p>${scene[0]}<small class="en">${scene[1]}</small></p><div class="mini-choices">${scene[3].map(choice=>`<button data-lesson-scene="${E(choice)}" data-correct="${choice===scene[2]}">${choice}</button>`).join('')}</div><small id="sceneFeedback">${m.sceneDone?'✓ Excellent choix ! — Great choice!':''}</small></article></div><div class="lesson-playground"><div class="flash-card"><span>🎴 Carte surprise — Surprise card</span><strong id="surpriseFrench">${target[0]}</strong><small id="surpriseEnglish">${target[1]}</small><div class="actions"><button class="btn" id="newLessonCard">Mélanger — Shuffle</button><button class="btn" data-speak-word="${E(target[0])}">🔊 Écouter — Listen</button></div></div><div class="speaking-mission"><span>${companion?.emoji||'🦊'}</span><div><h3>${companion?.name||'Ton guide'} te lance un défi !<small class="en">${companion?.name||'Your guide'} has a challenge!</small></h3><p>Écoute puis répète : <strong>${lessonExamples[j.current%lessonExamples.length].split(' — ')[0].replace('Exemple : ','')}</strong></p><button class="btn primary" id="lessonSpeakChallenge">🔊 Commencer le défi — Start challenge</button></div></div></div></section>`)}
function lessonQuestions(i){const sets=[[['Écris « Hello » en français.','Write “Hello” in French.','bonjour'],['Complète : Je m’___ Marie.','Complete: My name ___ Marie.','appelle'],['Comment dit-on “Nice to meet you” ?','How do you say “Nice to meet you”?','enchant']], [['Demande une baguette poliment.','Politely ask for a baguette.','baguette'],['Écris le mot français pour “please”.','Write the French word for “please”.','plaît'],['Comment demande-t-on le prix ?','How do you ask the price?','combien']], [['Traduis “tree”.','Translate “tree”.','arbre'],['Traduis “river”.','Translate “river”.','rivière'],['Traduis “bird”.','Translate “bird”.','oiseau']]];return (sets[i%sets.length]||sets[0]).map(x=>({q:x[0],en:x[1],a:x[2]}))}
function progressPage(){const quizzes=history.filter(x=>x.type==='quiz'),tests=history.filter(x=>x.type==='test'),stories=history.filter(x=>x.type==='story'),lessons=store.get('completedLessons',[]);const total=quizzes.length+tests.length+stories.length+lessons.length;$('#page').innerHTML=layout('Mes progrès','My progress','Chaque petit pas compte. Voici tout ce que tu as accompli. — Every small step matters. Here is what you have achieved.',`<div class="progress-hero"><div><span class="progress-star">⭐</span><strong>${total}</strong><p>activités accomplies<br><small>activities completed</small></p></div><div class="progress-ring" style="--value:${Math.min(100,total*10)}"><span>${Math.min(100,total*10)}%</span></div></div><div class="grid progress-grid"><article class="card"><span class="card-icon">📚</span><div class="stat">${lessons.length}</div>${B('leçons terminées','lessons completed')}</article><article class="card"><span class="card-icon">🏆</span><div class="stat">${quizzes.length}</div>${B('quiz terminés','quizzes completed')}</article><article class="card"><span class="card-icon">✍️</span><div class="stat">${tests.length}</div>${B('tests terminés','tests completed')}</article><article class="card"><span class="card-icon">✨</span><div class="stat">${stories.length}</div>${B('histoires créées','stories created')}</article></div><section class="card milestone"><h2>Prochain objectif<small class="en">Next milestone</small></h2><p>${total<10?`${10-total} activités avant ta prochaine étoile ! — ${10-total} activities until your next star!`:'Tu as gagné une étoile de progression ! — You earned a progress star!'}</p><div class="progress"><i style="width:${total%10*10}%"></i></div></section>`)}

const companions=[{id:'lumi',emoji:'🦊',name:'Lumi',role:'Guide curieuse — Curious guide',tone:'Encourageante et vive — Bright and encouraging',color:'coral'},{id:'noa',emoji:'🐼',name:'Noa',role:'Ami calme — Calm friend',tone:'Patient et rassurant — Patient and reassuring',color:'green'},{id:'celeste',emoji:'🦉',name:'Céleste',role:'Mentore sage — Wise mentor',tone:'Réfléchie et précise — Thoughtful and precise',color:'purple'},{id:'milo',emoji:'🐶',name:'Milo',role:'Partenaire joyeux — Cheerful partner',tone:'Joueur et énergique — Playful and energetic',color:'gold'}];
function companionPage(){const selected=store.get('companion',null);$('#page').innerHTML=layout('Mon compagnon','My companion','Choisis un ami, prends soin de lui, joue et pratique le français ensemble. — Choose a friend, care for them, play, and practice French together.',`<div class="companion-grid">${companions.map(c=>`<button class="companion-card companion-${c.color} ${selected===c.id?'selected':''}" data-companion="${c.id}"><span class="companion-avatar">${c.emoji}</span><h2>${c.name}</h2><strong>${c.role}</strong><p>${c.tone}</p><span class="btn">${selected===c.id?'✓ Sélectionné — Selected':'Choisir — Choose'}</span></button>`).join('')}</div>${selected?companionGame(selected)+`<section class="companion-preview card">${companionChat(selected,true)}</section>`:'<div class="card empty">Choisis ton compagnon pour commencer votre aventure. — Choose your companion to begin your adventure.</div>'}${avatarCreator()}`)}
function getPetState(id){return {...{hunger:72,happy:80,outfit:'none',lastFed:0},...store.get('pet_'+id,{})}}
function animateCompanionEating(food){const data={apple:{emoji:'🍎',fr:'une pomme',en:'an apple',phrase:'Je mange une pomme.',translation:'I am eating an apple.'},croissant:{emoji:'🥐',fr:'un croissant',en:'a croissant',phrase:'Je mange un croissant.',translation:'I am eating a croissant.'},carrot:{emoji:'🥕',fr:'une carotte',en:'a carrot',phrase:'Je mange une carotte.',translation:'I am eating a carrot.'}}[food],scene=$('.pet-scene'),pet=$('.pet-character');if(!data||!scene||!pet)return;scene.querySelector('.food-animation')?.remove();scene.querySelector('.food-word-card')?.remove();const bite=document.createElement('div');bite.className='food-animation';bite.textContent=data.emoji;scene.appendChild(bite);const card=document.createElement('div');card.className='food-word-card';card.innerHTML=`<span>${data.emoji}</span><div><strong>${data.fr}</strong><b>${data.en}</b><p>${data.phrase}<small>${data.translation}</small></p></div>`;scene.appendChild(card);pet.classList.add('eating');setTimeout(()=>{bite.classList.add('to-mouth')},50);setTimeout(()=>{bite.textContent='😋';pet.classList.add('chewing');speak(`${data.phrase} ${data.fr}.`,'fr-FR',{rate:.82})},850);setTimeout(()=>{bite.remove();pet.classList.remove('eating','chewing');card.classList.add('show')},1900);setTimeout(()=>card.classList.add('fade'),6500)}
function companionGame(id){const c=companions.find(x=>x.id===id),p=getPetState(id),outfits={none:'',hat:'🎩',crown:'👑',scarf:'🧣',glasses:'🕶️'};return `<section class="pet-room"><div class="pet-scene"><div class="pet-sparkles">✦　·　✧</div><div class="pet-character"><span class="pet-outfit">${outfits[p.outfit]}</span><span>${c.emoji}</span></div><h2>${c.name}</h2><button class="btn pet-speak" data-speak-companion="Bonjour ! Jouons et parlons français ensemble !">🔊 Fais-moi parler — Make me speak</button></div><div class="pet-controls"><h2>Prends soin de ${c.name}<small class="en">Take care of ${c.name}</small></h2><div class="pet-meter"><span>🍎 Faim — Hunger</span><div class="progress"><i style="width:${p.hunger}%"></i></div><b>${p.hunger}%</b></div><div class="pet-meter"><span>💛 Joie — Happiness</span><div class="progress"><i style="width:${p.happy}%"></i></div><b>${p.happy}%</b></div><div class="game-actions"><button class="game-btn" data-feed="apple">🍎<strong>Pomme</strong><small>Apple</small></button><button class="game-btn" data-feed="croissant">🥐<strong>Croissant</strong><small>Croissant</small></button><button class="game-btn" data-feed="carrot">🥕<strong>Carotte</strong><small>Carrot</small></button><button class="game-btn call" id="startCompanionCall">📹<strong>Appeler</strong><small>Video call</small></button></div><h3>Habiller — Dress up</h3><div class="outfit-row">${Object.entries(outfits).map(([key,icon])=>`<button class="outfit ${p.outfit===key?'selected':''}" data-outfit="${key}">${icon||'✓'}<small>${{none:'Simple',hat:'Chapeau',crown:'Couronne',scarf:'Écharpe',glasses:'Lunettes'}[key]}</small></button>`).join('')}</div></div></section>`}
function avatarCreator(){const member=user&&!user.guest,avatar=store.get('avatar',{icon:'🙂',color:'#ef806d',nickname:user?.name||''}),icons=['🙂','😎','🧑','👧','👦','🧒','🧑‍🎨','🧑‍🚀','🧙','🦸'];return `<section class="avatar-maker card"><div><p class="eyebrow">Mon avatar — My avatar</p><h2>Crée ton personnage<small class="en">Create your character</small></h2><p>${member?'Choisis ton visage, ta couleur et ton nom. — Choose your face, colour, and name.':'Connecte-toi ou crée un compte pour fabriquer ton propre avatar. — Log in or sign up to create your own avatar.'}</p></div>${member?`<div class="avatar-workshop"><div class="avatar-preview" id="avatarPreview" style="--avatar-color:${avatar.color}">${avatar.icon}</div><div><div class="avatar-icons">${icons.map(i=>`<button data-avatar-icon="${i}" class="${avatar.icon===i?'selected':''}">${i}</button>`).join('')}</div><div class="field"><label>Couleur — Color</label><input id="avatarColor" type="color" value="${avatar.color}"></div><div class="field"><label>Surnom — Nickname</label><input id="avatarName" maxlength="20" value="${E(avatar.nickname)}"></div><button class="btn primary" id="saveAvatar">Enregistrer mon avatar — Save my avatar</button></div></div>`:`<button class="btn primary" id="avatarLogin">Connexion / Créer un compte — Login / Sign up</button>`}</section>`}
function avatarPage(){if(!user||user.guest){$('#page').innerHTML=layout('Studio Avatar','Avatar Studio','Crée une identité unique pour ton parcours. — Create a unique identity for your journey.',`<section class="avatar-locked card"><div class="locked-art">🎨</div><h2>Le studio est réservé aux membres<small class="en">The studio is for members</small></h2><p>Connecte-toi ou crée un compte gratuit pour enregistrer ton avatar personnalisé. — Log in or create a free account to save your custom avatar.</p><button class="btn primary" id="avatarLogin">Connexion / Créer un compte — Login / Sign up</button></section>`);return}const a={icon:'🙂',color:'#ef806d',nickname:user.name,shape:'circle',accessory:'none',scene:'sunset',frame:'none',...store.get('avatar',{})},icons=['🙂','😄','😎','🤓','🧑','👧','👦','🧒','🧑‍🎨','🧑‍🚀','🧙','🦸'],accessories=[['none','Aucun','None'],['🎩','Chapeau','Hat'],['👑','Couronne','Crown'],['🎧','Casque','Headphones'],['🌸','Fleur','Flower'],['🕶️','Lunettes','Glasses']],shapes=[['circle','Cercle','Circle'],['squircle','Doux','Soft square'],['blob','Nuage','Blob']];$('#page').innerHTML=layout('Studio Avatar','Avatar Studio','Personnalise ton icône, ta couleur, sa forme et ses accessoires. — Customize your icon, colour, shape, and accessories.',`<div class="custom-avatar-studio"><aside class="avatar-stage" data-scene="${a.scene}"><div class="custom-avatar shape-${a.shape}" id="customAvatarPreview" data-icon="${a.icon}" data-shape="${a.shape}" data-accessory="${a.accessory}" data-frame="${a.frame}" style="--avatar-color:${a.color}"><span class="custom-accessory">${a.accessory==='none'?'':a.accessory}</span><span class="custom-face">${a.icon}</span></div><h2 id="avatarPreviewName">${E(a.nickname)}</h2><p>Ton avatar — Your avatar</p><div class="avatar-save-status" id="avatarSaveStatus">✓ Avatar chargé — Avatar loaded</div></aside><section class="avatar-options card"><div class="custom-group"><h3>1. Visage — Face</h3><div class="avatar-icons">${icons.map(i=>`<button data-custom-icon="${i}" class="${a.icon===i?'selected':''}" aria-label="Avatar ${i}">${i}</button>`).join('')}</div></div><div class="custom-group"><h3>2. Couleur — Colour</h3><div class="color-row">${['#ef806d','#efbd55','#65b596','#6da6d8','#937ac5','#df78a4','#526963'].map(c=>`<button data-custom-color="${c}" style="--swatch:${c}" class="color-swatch ${a.color===c?'selected':''}" aria-label="Couleur ${c}"></button>`).join('')}<input id="customAvatarColor" type="color" value="${a.color}" aria-label="Couleur personnalisée — Custom colour"></div></div><div class="custom-group"><h3>3. Forme — Shape</h3><div class="shape-row">${shapes.map(s=>`<button class="pill ${a.shape===s[0]?'active':''}" data-custom-shape="${s[0]}">${s[1]} — ${s[2]}</button>`).join('')}</div></div><div class="custom-group"><h3>4. Accessoire — Accessory</h3><div class="accessory-row">${accessories.map(x=>`<button data-custom-accessory="${x[0]}" class="accessory-choice ${a.accessory===x[0]?'selected':''}"><span>${x[0]==='none'?'✓':x[0]}</span><small>${x[1]}<br>${x[2]}</small></button>`).join('')}</div></div><div class="field"><label>5. Surnom — Nickname</label><input id="customAvatarName" maxlength="20" value="${E(a.nickname)}"></div><button class="btn primary save-custom" id="saveCustomAvatar">💾 Enregistrer mon avatar — Save my avatar</button></section></div>`)}
function companionMessage(id,page){const c=companions.find(x=>x.id===id),tips={home:'Prêt pour un petit pas aujourd’hui ? — Ready for one small step today?',lessons:'Prends ton temps : la régularité est plus importante que la vitesse. — Take your time: consistency matters more than speed.',quiz:'Lis bien chaque choix. Tu peux le faire ! — Read every choice carefully. You can do it!',tests:'Respire, puis réponds avec tes propres mots. — Breathe, then answer in your own words.',poems:'Écoute le rythme des mots. — Listen to the rhythm of the words.',activity:'Ton imagination n’a pas de mauvaise réponse. — Your imagination has no wrong answer.',progress:'Regarde tout le chemin que tu as déjà parcouru ! — Look how far you have already come!',settings:'Créons un espace confortable pour toi. — Let’s make your space comfortable.'};return `<div class="companion-says"><span>${c.emoji}</span><div><strong>${c.name} dit — says:</strong><p>${tips[page]||'Je suis là pour t’aider. — I am here to help you.'}</p></div></div>`}
function companionChat(id,full=false){const c=companions.find(x=>x.id===id),messages=store.get('companionChat_'+id,[]);return `<div class="chat-heading"><span class="companion-avatar small">${c.emoji}</span><div><h2>${c.name}</h2><p>En ligne — Online · Parle-moi en français !</p></div><button class="icon-btn" data-speak-companion="Bonjour ! Je suis ${c.name}. Parlons français ensemble.">🔊</button></div><div class="chat-messages ${full?'large':''}" id="chatMessages">${messages.length?messages.map(m=>`<div class="chat-message ${m.from}">${m.from==='bot'?`<button class="speak-inline" data-speak-companion="${m.text.replaceAll('"','&quot;')}">🔊</button>`:''}<p>${m.text}</p></div>`).join(''):`<div class="chat-message bot"><p>Bonjour ! Je suis ${c.name}. Comment vas-tu aujourd’hui ?</p><button class="speak-inline" data-speak-companion="Bonjour ! Comment vas-tu aujourd’hui ?">🔊</button></div>`}</div><div class="quick-prompts"><button data-chat-prompt="Bonjour !">Bonjour !</button><button data-chat-prompt="Aide-moi avec ma leçon.">Aide-moi</button><button data-chat-prompt="Apprenons un nouveau mot.">Nouveau mot</button></div><form class="companion-chat-form" data-companion-chat="${id}"><label class="sr-only" for="companionInput">Message en français — Message in French</label><input id="companionInput" name="message" placeholder="Écris en français… — Type in French…" autocomplete="off" required><button class="btn primary" type="submit" aria-label="Envoyer — Send">➤</button></form><p class="chat-note">${full?'Ton compagnon pratique des conversations simples hors ligne. — Your companion practices simple conversations offline.':''}</p>`}
function companionReply(text,id){const t=text.toLowerCase(),name=companions.find(x=>x.id===id).name;if(/bonjour|salut|coucou/.test(t))return `Bonjour ! Je suis très heureux de te voir. Comment vas-tu ?`;if(/ça va|ca va|vais bien|bien/.test(t))return `Super ! Moi aussi, ça va bien. Qu’aimerais-tu apprendre aujourd’hui ?`;if(/mal|triste|difficile/.test(t))return `Je comprends. Respire doucement. Nous pouvons avancer ensemble, un petit mot à la fois.`;if(/leçon|lecon|aide/.test(t))return `Bien sûr ! Lis chaque phrase à voix haute, puis écris une phrase personnelle avec le nouveau mot.`;if(/mot|vocabulaire/.test(t))return `Voici un mot : « courage ». Le courage signifie continuer même quand quelque chose semble difficile. Peux-tu créer une phrase ?`;if(/merci/.test(t))return `Avec plaisir ! En français, tu peux aussi dire « merci beaucoup ».`;if(/au revoir|à bientôt/.test(t))return `À bientôt ! Je serai ici pour continuer notre aventure en français.`;if(/comment.*appelles|ton nom/.test(t))return `Je m’appelle ${name}. Et toi, comment t’appelles-tu ?`;return `C’est intéressant ! Essaie de développer ta phrase. Tu peux commencer par « Je pense que… » ou « J’aime… parce que… ».`}
function openCompanionCall(){const id=store.get('companion',null),c=companions.find(x=>x.id===id);if(!c)return;const p=getPetState(id),outfits={none:'',hat:'🎩',crown:'👑',scarf:'🧣',glasses:'🕶️'},fr='Bonjour ! Je suis content de te voir. Comment vas-tu aujourd’hui ?',en='Hello! I am happy to see you. How are you today?';$('#modalBody').innerHTML=`<div class="video-call"><div class="call-status"><i></i> En appel avec ${c.name} — In a call</div><div class="call-stage"><div class="call-companion"><span class="call-outfit">${outfits[p.outfit]}</span>${c.emoji}<b>${c.name}</b></div><div class="self-video"><video id="selfVideo" autoplay muted playsinline></video><div id="cameraPlaceholder">📷<small>Caméra désactivée<br>Camera off</small></div></div><div class="call-caption" id="callCaption" aria-live="polite"><strong>${c.name}: ${fr}</strong><small>${en}</small></div></div><div class="call-controls"><button class="call-control" id="cameraToggle">📷<small>Caméra — Camera</small></button><button class="call-control" data-speak-companion="${fr}">🔊<small>Parler — Speak</small></button><button class="call-control end" id="endCompanionCall">☎<small>Terminer — End</small></button></div><p class="auth-note">Les sous-titres anglais apparaissent sous chaque phrase française. — English subtitles appear below every French sentence.<br>La caméra reste sur ton appareil et n’est jamais envoyée. — Camera video stays on your device and is never sent.</p></div>`;$('#modal').classList.add('open');$('#modal').setAttribute('aria-hidden','false');speak(fr,'fr-FR',{rate:.86})}
function enhanceAvatarStudio(){const options=$('.avatar-options'),preview=$('#customAvatarPreview');if(!options||!preview)return;const extraIcons=['🥰','🤩','🥳','🤠','🥸','🤖','👽','👻','🐱','🐶','🦊','🐼','🐯','🦁','🐸','🐵','🧚','🧜','🧛','🥷','👩‍🔬','👨‍🍳','👩‍🚒','👨‍🎤'];const iconBox=$('.avatar-icons');extraIcons.forEach(i=>iconBox.insertAdjacentHTML('beforeend',`<button data-custom-icon="${i}" aria-label="Avatar ${i}">${i}</button>`));const save=$('#saveCustomAvatar');save.insertAdjacentHTML('beforebegin',`<div class="custom-group ai-options"><div class="option-title"><h3>6. Décor — Background</h3><span>Inspiré par ChatGPT — ChatGPT-inspired</span></div><div class="scene-row">${[['sunset','🌅','Coucher de soleil'],['forest','🌲','Forêt'],['space','🚀','Espace'],['ocean','🌊','Océan'],['candy','🍭','Bonbons'],['rainbow','🌈','Arc-en-ciel']].map(x=>`<button data-avatar-scene="${x[0]}"><b>${x[1]}</b><small>${x[2]}</small></button>`).join('')}</div></div><div class="custom-group"><h3>7. Cadre — Frame</h3><div class="frame-row">${[['none','Aucun'],['stars','⭐ Étoiles'],['hearts','💗 Cœurs'],['leaves','🌿 Feuilles'],['sparkle','✨ Magique']].map(x=>`<button class="pill" data-avatar-frame="${x[0]}">${x[1]}</button>`).join('')}</div></div><button class="btn magic-mix" id="magicAvatar">✨ Mélange magique — Magic Mix</button>`);const saved=store.get('avatar',{}),stage=$('.avatar-stage');stage.dataset.scene=saved.scene||preview.closest('.avatar-stage').dataset.scene||'sunset';preview.dataset.frame=saved.frame||preview.dataset.frame||'none';$$('[data-custom-icon]').forEach(b=>b.classList.toggle('selected',b.dataset.customIcon===preview.dataset.icon));$$('[data-avatar-scene]').forEach(b=>b.classList.toggle('selected',b.dataset.avatarScene===stage.dataset.scene));$$('[data-avatar-frame]').forEach(b=>b.classList.toggle('active',b.dataset.avatarFrame===preview.dataset.frame));}
