 if(e.target.id==='testStart'){test.config={cat:$('#testCat').value,level:$('#testLevel').value,count:+$('#testCount').value,time:+$('#testTime').value};test.phase='run';test.i=0;test.answers=[];test.started=Date.now();test.saved=false;testRun()}if(e.target.id==='testPrev'||e.target.id==='testNext'){test.answers[test.i]=$('#written').value;test.i+=e.target.id==='testNext'?1:-1;testRun()}if(e.target.id==='testFinish')finishTest();if(e.target.id==='testRetake'){test={...test,phase:'setup',answers:[],i:0,saved:false};testSetup()}
