 const vo=e.target.closest('[data-voice]');if(vo){story.voice=vo.dataset.voice;story.step=2;saveStory();activityPage()}const ge=e.target.closest('[data-genre]');if(ge){story.genre=ge.dataset.genre;story.step=3;saveStory();activityPage()}const fl=e.target.closest('[data-flash]');if(fl){story.flash=fl.dataset.flash;story.step=4;saveStory();activityPage()}if(e.target.id==='suggest'){const ta=$('#storyText');ta.value+=(ta.value?'\n\n':'')+'Soudain, un petit bruit changea tout… — Suddenly, a tiny sound changed everything…';ta.dispatchEvent(new Event('input'))}if(e.target.id==='storyFinish'){story.text=$('#storyText').value.trim();if(story.text.length<20)return toast('Écris encore un peu — Please write a little more');story.finished=true;addHistory('story',story.text.split(/\s+/).slice(0,6).join(' ')+'…','',{text:story.text});saveStory();activityPage()}if(e.target.id==='storyEdit'){story.finished=false;story.step=4;saveStory();activityPage()}if(e.target.id==='storyCopy')copyText(story.text);if(e.target.id==='storyPrint')print();if(e.target.id==='storyDownload')download('mon-histoire.txt',story.text);if(e.target.id==='storyPlay'||e.target.id==='storyRestart')speak(story.text,'fr-FR',{rate:story.rate,volume:story.volume});if(e.target.id==='storyReset'){if(confirm('Tout effacer et recommencer ? — Clear everything and restart?')){stopSpeech();story={step:1,voice:'',genre:'',flash:'',text:'',finished:false,rate:.9,volume:1};saveStory();activityPage()}}
 if(e.target.id==='speechPause'&&speechSynthesis.speaking){speechSynthesis.pause();paused=true}if(e.target.id==='speechResume'&&paused){speechSynthesis.resume();paused=false}if(e.target.id==='speechStop')stopSpeech();
 const del=e.target.closest('[data-delete-history]');if(del&&confirm('Supprimer cette activité ? — Delete this activity?')){history=history.filter(x=>x.id!=del.dataset.deleteHistory);store.set('history',history);historyPage()}const op=e.target.closest('[data-open-story]');if(op){const h=history.find(x=>x.id==op.dataset.openStory);story={...story,text:h.data.text,finished:true,step:4};saveStory();go('activity')}if(e.target.id==='clearHistory'&&confirm('Effacer tout l’historique ? — Clear all history?')){history=[];store.set('history',history);historyPage()}
 if(e.target.id==='saveSettings'){settings.theme=$('#darkMode').checked?'dark':'light';settings.font=+$('#fontSize').value;settings.contrast=$('#contrast').checked;settings.reduced=$('#reduced').checked;settings.notifications=$('#notifications').checked;settings.rate=+$('#voiceRate').value;settings.music=$('#musicOn').checked;settings.volume=+$('#musicVolume').value;settings.track=$('input[name=track]:checked').value;saveSettings();settings.music?toggleMusic():stopMusic();toast('Paramètres enregistrés — Settings saved')}if(e.target.id==='resetSettings'&&confirm('Réinitialiser les paramètres ? — Reset settings?')){settings={...defaults};saveSettings();stopMusic();settingsPage()}const prev=e.target.closest('[data-preview]');if(prev){settings.music=true;toggleMusic(prev.dataset.preview);setTimeout(stopMusic,4000)}
