function authModal(){authTab='login';drawAuth();$('#modal').classList.add('open');$('#modal').setAttribute('aria-hidden','false')}
function authDraft(){try{return JSON.parse(localStorage.getItem('pm_authDraft'))||{}}catch{return {}}}
function saveAuthDraft(form){const old=authDraft(),name=form.elements.name?.value.trim()||old.name||'',email=form.elements.email?.value.trim()||old.email||'';localStorage.setItem('pm_authDraft',JSON.stringify({name,email,remember:!!form.elements.remember?.checked}))}
async function hashPassword(value){const bytes=new TextEncoder().encode('petit-monde-local-v1:'+value);if(globalThis.crypto?.subtle){const digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('')}let h=2166136261;bytes.forEach(b=>{h^=b;h=Math.imul(h,16777619)});return 'local-'+(h>>>0).toString(16)}
function localAccounts(){try{return JSON.parse(localStorage.getItem('pm_accounts'))||{}}catch{return {}}}
function saveLocalAccounts(accounts){localStorage.setItem('pm_accounts',JSON.stringify(accounts))}
function drawAuth(){const login=authTab==='login',draft=authDraft();$('#modalBody').innerHTML=`<h2 id="modalTitle">Bienvenue<small class="en">Welcome</small></h2><div class="tabs"><button class="tab ${login?'active':''}" data-auth-tab="login">Connexion — Login</button><button class="tab ${!login?'active':''}" data-auth-tab="signup">Créer un compte — Sign up</button></div><form id="authForm" name="${login?'login':'signup'}" novalidate>${!login?`<div class="field"><label>Nom — Name</label><input name="name" value="${E(draft.name||'')}" autocomplete="name" required></div>`:''}<div class="field"><label>Email — Email</label><input name="email" type="email" value="${E(draft.email||'')}" autocomplete="username email" required></div><div class="field"><label>Mot de passe — Password</label><div class="row"><input name="password" type="password" minlength="6" autocomplete="${login?'current-password':'new-password'}" required style="flex:1"><button class="btn" type="button" id="showPassword">Afficher — Show</button></div><small class="field-help">Ton mot de passe n’est jamais enregistré en texte lisible. — Your password is never saved as readable text.</small></div>${!login?'<div class="field"><label>Confirmer le mot de passe — Confirm password</label><input name="confirm" type="password" autocomplete="new-password" required></div><label><input name="terms" type="checkbox" required> J’accepte les conditions — I accept the terms</label>':`<label><input name="remember" type="checkbox" ${draft.remember?'checked':''}> Se souvenir de mon email — Remember my email</label><button class="btn forgot-btn" type="button" id="forgot">🔑 Mot de passe oublié — Forgot password</button>`}<p class="error" id="authError" role="alert"></p><button class="btn primary auth-submit" type="submit">${login?'Connexion — Login':'Créer un compte — Sign up'}</button></form><button class="btn" id="skipAuth">Passer pour le moment — Skip for now</button>`}
function drawPasswordReset(container){const draft=authDraft();container.innerHTML=`<div class="reset-auth"><span class="reset-icon">🔐</span><h2>Créer un nouveau mot de passe<small class="en">Create a new password</small></h2><p>Saisis l’email de ton compte et choisis un nouveau mot de passe. — Enter your account email and choose a new password.</p><form id="resetPasswordForm" novalidate><div class="field"><label>Email — Email</label><input name="email" type="email" value="${E(draft.email||'')}" autocomplete="username email" required></div><div class="field"><label>Nouveau mot de passe — New password</label><input name="password" type="password" minlength="6" autocomplete="new-password" required></div><div class="field"><label>Confirmer — Confirm</label><input name="confirm" type="password" autocomplete="new-password" required></div><p class="error" id="resetError" role="alert"></p><button class="btn primary" type="submit">Mettre à jour — Update password</button><button class="btn" type="button" id="backToLogin">← Retour à la connexion — Back to login</button></form><p class="auth-note">Réinitialisation locale : aucune donnée ne quitte cet appareil. — Local reset: no data leaves this device.</p></div>`}
function closeModal(){if(companionStream){companionStream.getTracks().forEach(t=>t.stop());companionStream=null}$('#modal').classList.remove('open');$('#modal').setAttribute('aria-hidden','true')}
function drawAuthGate(){drawAuth();$('#authGateBody').innerHTML=$('#modalBody').innerHTML;$('#authGateBody').insertAdjacentHTML('beforeend','<div class="progress-warning"><span>⚠️</span><p><strong>Important : connecte-toi pour sauvegarder tes progrès.</strong><small>Le mode invité est temporaire et les activités seront perdues après actualisation ou fermeture.</small><b>Important: sign in to save your progress.</b><small>Guest mode is temporary; activity is lost after refresh or closing.</small></p></div><p class="auth-note">🔒 Tes informations restent sur cet appareil. Cette démonstration ne transmet aucune donnée à un serveur.<small class="en">Your information stays on this device. This demo sends no data to a server.</small></p>');closeModal();}
function showAuthGate(){authTab='login';document.body.classList.add('auth-required');$('.companion-widget')?.remove();drawAuthGate();setTimeout(()=>$('#authGateBody input')?.focus(),0)}
async function finishAuth(form,errorTarget){const f=new FormData(form),err=errorTarget,email=String(f.get('email')||'').trim().toLowerCase(),password=String(f.get('password')||''),accounts=localAccounts();err.textContent='';saveAuthDraft(form);if(!/^\S+@\S+\.\S+$/.test(email)){err.textContent='Adresse email invalide — Invalid email address';return false}if(password.length<6){err.textContent='6 caractères minimum — At least 6 characters';return false}const passwordHash=await hashPassword(password);if(authTab==='signup'){const name=String(f.get('name')||'').trim();if(name.length<2){err.textContent='Entre ton nom — Enter your name';return false}if(password!==f.get('confirm')){err.textContent='Les mots de passe diffèrent — Passwords do not match';return false}if(!f.get('terms')){err.textContent='Accepte les conditions — Please accept the terms';return false}if(accounts[email]){err.textContent='Un compte existe déjà. Utilise Connexion. — An account already exists. Use Login.';return false}accounts[email]={name,email,passwordHash,createdAt:new Date().toISOString()};saveLocalAccounts(accounts)}else{const account=accounts[email];if(!account){err.textContent='Compte introuvable. Crée d’abord un compte. — Account not found. Please sign up first.';return false}if(account.passwordHash!==passwordHash){err.textContent='Mot de passe incorrect — Incorrect password';return false}}const account=accounts[email];user={name:account.name,email:account.email};store.set('user',user);localStorage.setItem('pm_authDraft',JSON.stringify({name:user.name,email:user.email,remember:!!f.get('remember')}));form.reset();document.body.classList.remove('auth-required');closeModal();go('home');render();toast(authTab==='signup'?'Compte créé ! — Account created!':'Connexion réussie ! — Logged in!');return true}
async function resetLocalPassword(form,errorTarget){const f=new FormData(form),email=String(f.get('email')||'').trim().toLowerCase(),password=String(f.get('password')||''),err=errorTarget,accounts=localAccounts();err.textContent='';if(!accounts[email]){err.textContent='Aucun compte avec cet email — No account with this email';return false}if(password.length<6){err.textContent='6 caractères minimum — At least 6 characters';return false}if(password!==f.get('confirm')){err.textContent='Les mots de passe diffèrent — Passwords do not match';return false}accounts[email].passwordHash=await hashPassword(password);accounts[email].updatedAt=new Date().toISOString();saveLocalAccounts(accounts);localStorage.setItem('pm_authDraft',JSON.stringify({name:accounts[email].name,email,remember:true}));toast('Mot de passe mis à jour — Password updated');authTab='login';return true}
queueMicrotask(()=>{if(!user)showAuthGate();else document.body.classList.remove('auth-required')});
$('#authGateBody').addEventListener('input',e=>{if(e.target.closest('#authForm'))saveAuthDraft(e.target.form)});
$('#authGateBody').addEventListener('click',e=>{const tab=e.target.closest('[data-auth-tab]');if(tab){authTab=tab.dataset.authTab;drawAuthGate()}if(e.target.id==='showPassword'){const p=$('[name=password]',$('#authGateBody'));p.type=p.type==='password'?'text':'password'}if(e.target.id==='forgot')drawPasswordReset($('#authGateBody'));if(e.target.id==='backToLogin'){authTab='login';drawAuthGate()}if(e.target.id==='skipAuth'){window.pmGuest=true;user={name:'Invité',guest:true};history=[];favorites=[];story={step:1,voice:'',genre:'',flash:'',text:'',finished:false,rate:.9,volume:1};document.body.classList.remove('auth-required');go('home');render();toast('Mode invité : progrès non sauvegardé — Guest progress is not saved')}});
$('#authGateBody').addEventListener('submit',async e=>{e.preventDefault();window.pmGuest=false;if(e.target.id==='resetPasswordForm'){if(await resetLocalPassword(e.target,$('#resetError',$('#authGateBody'))))drawAuthGate();return}await finishAuth(e.target,$('#authError',$('#authGateBody')))});
$('#modal').addEventListener('input',e=>{if(e.target.closest('#authForm'))saveAuthDraft(e.target.form)});
$('#modal').addEventListener('click',e=>{const tab=e.target.closest('[data-auth-tab]');if(tab){authTab=tab.dataset.authTab;drawAuth()}if(e.target.id==='showPassword'){const p=$('[name=password]',$('#modal'));p.type=p.type==='password'?'text':'password'}if(e.target.id==='forgot')drawPasswordReset($('#modalBody'));if(e.target.id==='backToLogin'){authTab='login';drawAuth()}if(e.target.id==='skipAuth')closeModal()});
$('#modal').addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='resetPasswordForm'){if(await resetLocalPassword(e.target,$('#resetError',$('#modal'))))drawAuth();return}await finishAuth(e.target,$('#authError',$('#modal')))});
$('#modalClose').onclick=closeModal;$('#authOpen').onclick=authModal;$('#authTop').onclick=authModal;$('#menuBtn').onclick=()=>{const open=$('#sidebar').classList.toggle('open');document.body.classList.toggle('menu-open',open)};$('#navScrim').onclick=()=>{$('#sidebar').classList.remove('open');document.body.classList.remove('menu-open')};$('#musicToggle').onclick=()=>{settings.music=!settings.music;saveSettings();settings.music?toggleMusic():stopMusic();$('#musicToggle').classList.toggle('active',settings.music);toast(settings.music?'Musique activée — Music on':'Musique arrêtée — Music off')};window.addEventListener('hashchange',render);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#sidebar').classList.remove('open');document.body.classList.remove('menu-open')}});applySettings();render();
